const authCodeHits=new Map();function authCodeAllowed(req){const key=crypto.createHash('sha256').update(String(req.ip||'unknown')+'|'+String(req.get('user-agent')||'')).digest('hex');const now=Date.now(),x=authCodeHits.get(key)||{at:now,count:0};if(now-x.at>10*60*1000){x.at=now;x.count=0}x.count++;authCodeHits.set(key,x);return x.count<=8}
const publicHits=new Map();
function publicRate(req,res,next){const now=Date.now(),key=req.ip||'unknown',x=publicHits.get(key)||{at:now,count:0};if(now-x.at>60000){x.at=now;x.count=0}if(++x.count>40)return res.status(429).json({error:'Trop de requêtes. Réessaie dans une minute.'});publicHits.set(key,x);next()}
function publicScope(req){const id=publicGuildId();const requested=clean(req.query.guild_id||req.body?.guild_id||id,30);return id&&requested===id?id:null}
const applicationChallenges=new Map();
const applicationAttemptWindow=new Map();
function applicationFingerprint(req){const raw=`${req.ip||''}|${req.get('user-agent')||''}`;return crypto.createHash('sha256').update(raw).digest('hex')}
function issueApplicationChallenge(req){const a=crypto.randomInt(2,10),b=crypto.randomInt(2,10);const token=crypto.randomBytes(18).toString('hex');applicationChallenges.set(token,{answer:a+b,expires:Date.now()+10*60*1000,session:req.sessionID});return{token,question:`Combien font ${a} + ${b} ?`}}
function validateApplicationChallenge(req,token,answer){const c=applicationChallenges.get(String(token||''));if(!c||c.expires<Date.now()||c.session!==req.sessionID){if(token)applicationChallenges.delete(String(token));return false}applicationChallenges.delete(String(token));return Number(answer)===c.answer}
function applicationAttemptAllowed(req,guildId){const key=applicationFingerprint(req);const now=Date.now(),row=applicationAttemptWindow.get(key)||{at:now,count:0};if(now-row.at>10*60*1000){row.at=now;row.count=0}row.count++;applicationAttemptWindow.set(key,row);return row.count<=8}

app.get('/auth/player/login',(req,res)=>{const state=crypto.randomBytes(32).toString('base64url');req.session.oauthState=state;req.session.save(err=>{if(err)return res.status(500).send('Impossible de préparer la connexion Discord.');const redirect=`${SITE_BASE_URL}/auth/player/callback`;const p=new URLSearchParams({client_id:process.env.DISCORD_CLIENT_ID,response_type:'code',redirect_uri:redirect,scope:'identify'});res.redirect(`https://discord.com/oauth2/authorize?${p}&state=${encodeURIComponent(state)}`)});});
app.get('/auth/player/login/:token',async(req,res)=>{try{const raw=clean(req.params.token,200);if(!/^[A-Za-z0-9_-]{40,100}$/.test(raw))return res.status(401).send('Lien de connexion invalide.');const hash=crypto.createHash('sha256').update(raw).digest('hex');const link=getLoginLinkByHash(hash);if(!link)return res.status(401).send('Ce lien de connexion a été révoqué ou est invalide.');const guild=client.guilds.cache.get(link.guild_id)||await client.guilds.fetch(link.guild_id).catch(()=>null);if(!guild)return res.status(503).send('Serveur Discord indisponible.');const member=guild.members.cache.get(link.user_id)||await guild.members.fetch(link.user_id).catch(()=>null);if(!member)return res.status(403).send('Ton compte Discord n’est plus présent sur le serveur LS CUSTOM.');const employee=getEmployees(link.guild_id).find(e=>String(e.user_id)===String(link.user_id));if(!employee||employee.status==='inactive')return res.status(403).send('Ton profil LS CUSTOM n’est plus actif.');touchLoginLink(link.id);establishPlayerSession(req,{id:link.user_id,username:member.user.username,global_name:member.displayName||member.user.globalName||member.user.username,avatar:member.user.avatar,guildId:link.guild_id,login:'persistent-link',loginLinkId:link.id},err=>{if(err)return res.status(500).send('Impossible de créer la session.');try{audit(link.guild_id,link.user_id,'employee.login_persistent',String(link.id))}catch{}res.redirect('/dashboard')})}catch(e){console.error('Lien de connexion persistant:',e);res.status(500).send('Connexion automatique impossible.')}});
app.get('/auth/player/callback',async(req,res)=>{try{const state=clean(req.query.state,200);if(!state||state!==req.session.oauthState)return res.status(400).send('État de connexion Discord invalide.');delete req.session.oauthState;const redirect=`${SITE_BASE_URL}/auth/player/callback`;const body=new URLSearchParams({client_id:process.env.DISCORD_CLIENT_ID,client_secret:process.env.DISCORD_CLIENT_SECRET,grant_type:'authorization_code',code:req.query.code,redirect_uri:redirect});const tr=await fetch('https://discord.com/api/oauth2/token',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body});const token=await tr.json();if(!tr.ok||!token.access_token)throw Error(token.error_description||'OAuth token absent');const user=await fetch('https://discord.com/api/users/@me',{headers:{Authorization:`Bearer ${token.access_token}`}}).then(r=>r.json());const guildId=publicGuildId();if(!guildId)throw Error('Serveur LS CUSTOM non configuré.');const access=await getMemberAccess(guildId,user.id);if(!access) return res.status(403).send('Ton compte Discord ne fait pas partie du serveur LS CUSTOM.');if(!access.employee) return res.status(403).send('Ton compte Discord est bien reconnu, mais il n’est pas encore inscrit dans l’équipe LS CUSTOM.');establishPlayerSession(req,{id:user.id,username:user.username,global_name:user.global_name||user.username,avatar:user.avatar,guildId,login:'discord-oauth'},err=>{if(err)throw err;res.redirect('/dashboard')})}catch(e){res.status(500).send(`Connexion Discord échouée : ${e.message}`)}});
app.post('/api/developer/impersonation/start/:id',playerAuth,async(req,res)=>{
 try{
  const a=await developerAccess(req);
  if(!a)return res.status(403).json({error:'Accès développeur réservé.'});
  if(req.session.impersonation)return res.status(409).json({error:'Une session utilisateur est déjà ouverte.'});
  const g=req.session.player.guildId,id=Number(req.params.id),employee=getEmployees(g).find(e=>Number(e.id)===id);
  if(!employee)return res.status(404).json({error:'Utilisateur introuvable.'});

  // Le profil simulé est TOUJOURS local. Aucun ID Discord n'est réutilisé.
  const targetId=`impersonate:${employee.id}`;
  const original={...req.session.player};

  // Rotation de l'ID de session : le cookie de session précédent est invalidé.
  req.session.regenerate(err=>{
    if(err)return res.status(500).json({error:'Impossible de sécuriser la session développeur.'});
    req.session.impersonation={
      originalPlayer:original,
      developerId:original.id,
      targetId,
      targetEmployeeId:employee.id,
      startedAt:Date.now(),
      developerOnly:true
    };
    req.session.player={
      id:targetId,
      username:employee.username||'',
      global_name:employee.display_name||employee.username||'Utilisateur',
      avatar:null,
      guildId:g,
      login:'developer-impersonation',
      impersonated:true
    };
    req.session.save(saveErr=>{
      if(saveErr)return res.status(500).json({error:'Impossible d’enregistrer la session développeur sécurisée.'});
      audit(g,original.id,'developer.impersonation.started',JSON.stringify({employeeId:employee.id,targetId,discordLinked:false,sessionRotated:true}));
      res.json({ok:true,redirect:'/dashboard',user:{id:targetId,display_name:employee.display_name}});
    });
  });
 }catch(e){
  console.error('Démarrage impersonation:',e);
  res.status(500).json({error:'Impossible d’ouvrir la session utilisateur.'});
 }
});
app.post('/api/developer/impersonation/stop',playerAuth,async(req,res)=>{
 try{
  const imp=req.session.impersonation;
  if(!imp?.originalPlayer||!imp.developerOnly)return res.status(400).json({error:'Aucune session développeur à restaurer.'});
  const current={...req.session.player};
  const original={...imp.originalPlayer};
  req.session.regenerate(err=>{
    if(err)return res.status(500).json({error:'Impossible de sécuriser la restauration de session.'});
    req.session.player=original;
    req.session.save(saveErr=>{
      if(saveErr)return res.status(500).json({error:'Impossible de restaurer la session développeur.'});
      audit(original.guildId,original.id,'developer.impersonation.stopped',JSON.stringify({targetId:current?.id||imp.targetId,targetEmployeeId:imp.targetEmployeeId,sessionRotated:true}));
      res.json({ok:true,redirect:'/developpeur'});
    });
  });
 }catch(e){
  console.error('Arrêt impersonation:',e);
  res.status(500).json({error:'Impossible de restaurer la session développeur.'});
 }
});
