app.post('/api/auth/code/verify',async(req,res)=>{try{if(!authCodeAllowed(req))return res.status(429).json({error:'Trop de tentatives de connexion. Réessaie dans quelques minutes.'});const raw=clean(req.body.code,20).replace(/\s/g,'');if(!/^\d{6}$/.test(raw))return res.status(400).json({error:'Code invalide.'});const hash=crypto.createHash('sha256').update(raw).digest('hex');const row=consumeLoginCode(hash);if(!row)return res.status(401).json({error:'Code expiré, invalide ou déjà utilisé.'});if(!row.guild_id||!row.user_id)return res.status(401).json({error:'Code de connexion invalide.'});let access=null;try{access=await getMemberAccess(row.guild_id,row.user_id)}catch(e){console.error('Erreur vérification Discord du code:',e);return res.status(503).json({error:'Impossible de vérifier ton compte Discord pour le moment. Vérifie que le bot est connecté puis réessaie.'})}if(!access)return res.status(403).json({error:'Ton compte Discord n’est plus accessible sur le serveur LS CUSTOM.'});establishPlayerSession(req,{id:row.user_id,username:row.username||access.username,global_name:access.displayName,guildId:row.guild_id,login:'temporary-code'},err=>{if(err){console.error('Erreur sauvegarde session joueur:',err);return res.status(500).json({error:'Connexion créée mais impossible d’enregistrer la session. Réessaie.'})}try{audit(row.guild_id,row.user_id,'employee.login','temporary-code')}catch(e){console.error('Erreur audit connexion:',e)}res.json({ok:true,user:{id:row.user_id},redirect:'/dashboard'})})}catch(e){console.error('Erreur /api/auth/code/verify:',e);res.status(500).json({error:'Impossible de valider le code.'})}});
