async function employeeAnnouncementAccess(req){
  const a=await getMemberAccess(req.session.player.guildId,req.session.player.id);
  if(!a)return null;
  return {access:a,canManage:Boolean(a.isAdmin||a.permissions.includes('announcements_manage')||a.permissions.includes('all'))};
}
