function mailEmployeeIdentity(req){const p=req.session.player;return{type:'employee',id:effectiveEmployeeUserId(req),name:p.display_name||p.global_name||p.username||'Employé'}}
function mailClientIdentity(req,p){return{type:'client',id:String(p.id),name:p.company||p.contact||'Client'}}
async function employeeMailRecipient(req,type,id){
  const g=req.session.player.guildId;
  const contacts=getMailContacts(g);
  const t=String(type),i=String(id);
  if(t==='employee')return contacts.employees.find(x=>String(x.id)===i)||null;
  if(t==='client')return contacts.clients.find(x=>String(x.id)===i)||null;
  return null;
}
