 const fingerprint=applicationFingerprint(req);
 if(countSecurityAttempts(g,fingerprint,10)>=8)return res.status(429).json({error:'Trop de tentatives. Réessaie dans quelques minutes.'});
 recordSecurityAttempt(g,fingerprint);
 const honeypot=clean(req.body.website_url,200);
 if(honeypot)return res.status(400).json({error:'Formulaire invalide.'});
 if(!validateApplicationChallenge(req,req.body.challenge_token,req.body.challenge_answer))return res.status(400).json({error:'Vérification anti-robot incorrecte. Recharge le formulaire.'});
 const nom=clean(req.body.nom,60),prenom=clean(req.body.prenom,60),rpId=clean(req.body.rp_id,30),age=Number(req.body.age),discordId=clean(req.body.discord_id||req.session.player?.id,30),presentation=clean(req.body.presentation,2500),motivation=clean(req.body.motivation,3000),experience=clean(req.body.experience,2500);
 if(!nom||!prenom||!rpId||!/^d{17,20}$/.test(discordId)||!presentation||!motivation||!experience||!Number.isInteger(age)||age<15||age>99)return res.status(400).json({error:'Tous les champs obligatoires doivent être correctement remplis.'});
 const identity=`discord:${discordId}`;
 if(hasRecentApplication(r.id,identity,30))return res.status(429).json({error:'Une candidature récente existe déjà pour ce recrutement avec ce compte Discord.'});
 if(countRecentApplicationsByIdentity(g,identity,24)>=3)return res.status(429).json({error:'Ce compte Discord a déjà envoyé plusieurs candidatures récemment. Réessaie demain.'});
 const answers={nom,prenom,rp_id:rpId,age,discord_id:discordId,presentation,motivation,experience,source:req.session.player?'discord':'web'};
 for(const q of parseJson(r.questions_json,[])){const key=clean(q.key,40);const value=clean(req.body[key],3000);if(key&&q.required!==false&&!value)return res.status(400).json({error:`La question « ${q.label} » est obligatoire.`});if(key)answers[key]=value}
 const days=['lundi','mardi','mercredi','jeudi','vendredi','samedi','dimanche'];
 const availability={};
 for(const day of days){const enabled=req.body[`dispo_${day}`] === 'on';const from=clean(req.body[`dispo_${day}_from`],5),to=clean(req.body[`dispo_${day}_to`],5);if(enabled){if(!/^([01]\\d|2[0-3]):[0-5]\\d$/.test(from)||!/^([01]\\d|2[0-3]):[0-5]\\d$/.test(to)||from>=to)return res.status(400).json({error:`Disponibilité invalide pour ${day}.`});availability[day]={from,to}}}
 if(!Object.keys(availability).length)return res.status(400).json({error:'Indique au moins une disponibilité.'});
