app.get('/api/guilds/:guildId/partnership-tickets',playerAuth,async(req,res)=>{const g=req.params.guildId;try{const a=await getMemberAccess(g,req.session.player.id);if(!a)return res.status(403).json({error:'Accès refusé.'});const admin=a.isAdmin||a.permissions.includes('partnerships')||a.permissions.includes('all');if(!admin)return res.status(403).json({error:'Accès partenariats refusé.'});const guild=client.guilds.cache.get(g)||await client.guilds.fetch(g).catch(()=>null);if(!guild)return res.status(404).json({error:'Serveur Discord introuvable.'});const categoryId=getSetting(g,'partnership_category')||process.env.PARTNERSHIP_TICKET_CATEGORY_ID||'1549137158919430255';const channels=await guild.channels.fetch();const result=[];for(const ch of channels.values()){if(!ch||ch.parentId!==categoryId||!ch.isTextBased?.())continue;let creatorId=null;for(const [id,ow] of ch.permissionOverwrites.cache){if(ow.type===1&&id!==guild.id){creatorId=id;break}}let creator=null;if(creatorId)creator=await guild.members.fetch(creatorId).catch(()=>null);let message='';try{const msgs=await ch.messages.fetch({limit:30});const first=[...msgs.values()].sort((x,y)=>x.createdTimestamp-y.createdTimestamp).find(m=>!m.author.bot&&String(m.content||'').trim());if(first)message=String(first.content||'').trim().slice(0,2000)}catch{}{const linked=getPartnershipByDiscordChannel(g,ch.id);if(linked)continue;result.push({id:ch.id,name:ch.name,url:ch.url,createdAt:ch.createdAt?.toISOString()||null,creatorId,creatorName:creator?.displayName||creator?.user?.username||null,message})}}res.json(result.sort((a,b)=>String(a.createdAt).localeCompare(String(b.createdAt))))}catch(e){console.error(e);res.status(500).json({error:'Impossible de lire la catégorie Ticket Tool.'})}});
