app.get('/api/pilotage/overview',playerAuth,async(req,res)=>{try{const g=req.session.player.guildId,a=await getMemberAccess(g,req.session.player.id);if(!a)return res.status(403).json({error:'Accès refusé.'});const limited=!a.isAdmin&&a.permissions.length===0;if(limited)return res.json({limited:true,employee:a.employee||null,notifications:getNotifications(g,effectiveEmployeeUserId(req),20),sanctions:a.employee?getSanctions(g,a.employee.id):[],badges:a.employee?getEmployeeBadges(g).filter(x=>x.employee_id===a.employee.id):[]});const now=new Date(),end=now.toISOString().slice(0,10),start=new Date(now-6*86400000).toISOString().slice(0,10);const employees=getEmployees(g),analytics=organisationAnalytics(g,start,end),quotaFollowup=getQuotaFollowup(g),notifications=getNotifications(g,effectiveEmployeeUserId(req),30),sanctions=getSanctions(g),badges=getEmployeeBadges(g);let sessions=0;try{sessions=Number(db.prepare('SELECT COUNT(*) AS n FROM web_sessions WHERE expires_at>?').get(Date.now())?.n||0)}catch{}const discord=client.guilds.cache.get(g);res.json({limited:false,employee:a.employee||null,employees,analytics,quotaFollowup,notifications,badges,sessions,discord:discord?{id:discord.id,name:discord.name,members:discord.memberCount}:null,uptime:process.uptime(),now:end,permissions:a.permissions,isAdmin:a.isAdmin})}catch(e){console.error('Pilotage overview:',e);res.status(500).json({error:'Impossible de charger le centre de pilotage.'})}});
app.post('/api/pilotage/notifications/:id/read',playerAuth,async(req,res)=>{const g=req.session.player.guildId;if(markNotificationRead(Number(req.params.id),g,effectiveEmployeeUserId(req)))return res.json({ok:true});res.status(404).json({error:'Notification introuvable.'})});
app.post('/api/pilotage/sanctions',playerAuth,async(req,res)=>{try{const g=req.session.player.guildId,a=await getMemberAccess(g,req.session.player.id);if(!a||(!a.isAdmin&&!a.permissions.includes('team')&&!a.permissions.includes('all')))return res.status(403).json({error:'Permission RH requise.'});const employeeId=Number(req.body.employee_id);const employee=getEmployees(g).find(e=>e.id===employeeId);if(!employee)return res.status(404).json({error:'Employé introuvable.'});const reason=clean(req.body.reason,1000),type=clean(req.body.type,40);if(!reason||!['avertissement','blame','mise_a_pied','exclusion'].includes(type))return res.status(400).json({error:'Type ou motif invalide.'});const s=createSanction({guildId:g,employeeId,type,reason,startsAt:clean(req.body.starts_at,30)||new Date().toISOString(),endsAt:clean(req.body.ends_at,30)||null,createdBy:req.session.player.id});createNotification({guildId:g,userId:employee.user_id,type:'warning',title:'Nouvelle mesure RH',message:'Une mesure RH a été ajoutée à ton dossier.',link:'/pilotage'});audit(g,req.session.player.id,'rh.sanction.created',JSON.stringify({employeeId,type}));res.status(201).json({ok:true,sanction:s})}catch(e){console.error(e);res.status(500).json({error:'Impossible de créer la mesure RH.'})}});
app.delete('/api/pilotage/sanctions/:id',playerAuth,async(req,res)=>{try{const g=req.session.player.guildId,a=await getMemberAccess(g,req.session.player.id);if(!a||(!a.isAdmin&&!a.permissions.includes('team')&&!a.permissions.includes('all')))return res.status(403).json({error:'Permission RH requise.'});if(!deleteSanction(Number(req.params.id),g))return res.status(404).json({error:'Mesure introuvable.'});audit(g,req.session.player.id,'rh.sanction.deleted',req.params.id);res.json({ok:true})}catch(e){res.status(500).json({error:'Impossible de supprimer la mesure.'})}});
app.post('/api/pilotage/badges/recalculate',playerAuth,async(req,res)=>{try{const g=req.session.player.guildId,a=await getMemberAccess(g,req.session.player.id);if(!a||(!a.isAdmin&&!a.permissions.includes('activity_all')&&!a.permissions.includes('all')))return res.status(403).json({error:'Permission activité requise.'});const badges=getBadges(g),employees=getEmployees(g),now=new Date(),end=now.toISOString().slice(0,10),start=new Date(now-6*86400000).toISOString().slice(0,10),rows=getQuotaEntries(g,start,end);let awarded=0;for(const e of employees){const rs=rows.filter(r=>r.employee_id===e.id);const total=rs.reduce((n,r)=>n+(Number(r.reparations)||0)+(Number(r.fourrieres)||0)+(Number(r.appels)||0)+(Number(r.personnalisations)||0)+(Number(r.factures)||0),0);const amount=rs.reduce((n,r)=>n+(Number(r.montant_fourrieres)||0)+(Number(r.montant_personnalisations)||0)+(Number(r.montant_factures)||0),0);if(e.quota_enabled&&Number(e.quota_target)>0&&amount>=Number(e.quota_target)){awardBadge(g,e.id,'quota_master');awarded++}if(total>=100){awardBadge(g,e.id,'activity');awarded++}if(rs.reduce((n,r)=>n+(Number(r.reparations)||0),0)>=50){awardBadge(g,e.id,'repair_pro');awarded++}if(rs.reduce((n,r)=>n+(Number(r.fourrieres)||0),0)>=25){awardBadge(g,e.id,'fourriere_pro');awarded++}}audit(g,req.session.player.id,'badges.recalculated',String(awarded));res.json({ok:true,awarded})}catch(e){console.error(e);res.status(500).json({error:'Impossible de recalculer les badges.'})}});
app.get('/api/pilotage/security',playerAuth,async(req,res)=>{try{const g=req.session.player.guildId,a=await getMemberAccess(g,req.session.player.id);if(!a||(!a.isAdmin&&!a.permissions.includes('audit')&&!a.permissions.includes('all')))return res.status(403).json({error:'Permission audit requise.'});let sessions=[];try{sessions=db.prepare("SELECT sid,expires_at FROM web_sessions WHERE expires_at>? ORDER BY expires_at DESC LIMIT 100").all(Date.now()).map(x=>({id:x.sid.slice(0,8)+'…',expiresAt:x.expires_at}))}catch{}res.json({sessions,audit:getAuditLogs(g,100)})}catch(e){res.status(500).json({error:'Impossible de charger la sécurité.'})}});

app.get(/.*/,(req,res)=>res.sendFile(path.resolve('public/portal.html')));
export function startDashboard(){app.listen(Number(process.env.PORT||3000),()=>console.log(`🌐 Site : ${process.env.BASE_URL||`http://localhost:${process.env.PORT||3000}`}`))}
